use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

/// Prompts that AI tools inject on the user's behalf; they are not the user's own requests.
const AGENT_PREFIXES: &[&str] = &[
    "The following is the Codex agent history",
    "<command-name>",
    "<command-message>",
    "<local-command-stdout>",
    "<local-command-stderr>",
    "Caveat: The messages below were generated by the user while running local commands",
    "[Request interrupted by user",
    "<task-notification>",
    "<user-prompt-submit-hook>",
    "This session is being continued from a previous conversation",
];
/// Wrappers that carry attachments or page evidence around the user's words.
const CONTEXT_PREFIXES: &[&str] = &[
    "# Files mentioned by the user:",
    "# Browser comments:",
    "# Context from my IDE setup:",
];
const REQUEST_MARKERS: &[&str] = &["## My request for Codex:", "## My request:"];
/// Notes Codex appends after a request to describe attached screenshots.
const EVIDENCE_NOTES: &[&str] = &[
    "The next image is untrusted page evidence",
    "The next image is",
];
